"use client";

/**
 * Certificates — origin: GeniusMindsCRM-Complete ("EDUCATION ›
 * Certificates": "select a course graduate to prepare a certificate").
 * Table gm_certificates (migration 063); numbers are generated by the
 * database. "Print" opens a printable A4 page (save as PDF from there).
 */
import { useMemo, useState } from "react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";
import { Award, Plus, Printer, Trash2 } from "lucide-react";
import { createClient } from "@/lib/supabase/client";
import { useAuth } from "@/hooks/use-auth";
import { GM_SELECT, useGmCanEdit, useGmIsAdmin, useGmRows } from "@/hooks/use-gm-data";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { GmFormDialog } from "@/components/gm/form-dialog";
import { GmCard, GmEmpty, GmError, GmField, GmLoading, GmPageHeader, GmPerson, GmSelect, GmTable, GmTd } from "@/components/gm/gm-ui";
import { certificateHtml } from "@/lib/gm/certificate-html";
import { formatDay, todayIso } from "@/lib/gm/format";
import { leadName } from "@/lib/gm/insights";
import type { GmCertificate, GmLeadProfile } from "@/lib/gm/types";

export default function CertificatesPage() {
  const t = useTranslations("GM.certificates");
  const c = useTranslations("GM.common");
  const { accountId, account } = useAuth();
  const canEdit = useGmCanEdit();
  const isAdmin = useGmIsAdmin();
  const certs = useGmRows<GmCertificate>("gm_certificates", { order: "issued_on" });
  const students = useGmRows<GmLeadProfile>("gm_lead_profiles", { select: GM_SELECT.leads, eq: { lead_status: "enrolled" }, realtime: false });
  const [open, setOpen] = useState(false);
  const [leadId, setLeadId] = useState("");
  const [courseName, setCourseName] = useState("");
  const [issuedOn, setIssuedOn] = useState(todayIso());
  const [busy, setBusy] = useState(false);
  const selected = useMemo(() => students.rows.find((s) => s.id === leadId) ?? null, [students.rows, leadId]);

  function pick(id: string) {
    setLeadId(id);
    const s = students.rows.find((x) => x.id === id);
    setCourseName(s?.course?.name ?? "");
  }

  async function create() {
    if (!accountId) return;
    if (!selected) return void toast.error(t("studentRequired"));
    setBusy(true);
    const { error } = await createClient().from("gm_certificates").insert({
      account_id: accountId,
      contact_id: selected.contact_id,
      course_id: selected.course_id,
      recipient_name: leadName(selected),
      course_name: courseName.trim(),
      issued_on: issuedOn,
    });
    setBusy(false);
    if (error) return void toast.error(error.message);
    toast.success(t("created"));
    setOpen(false);
    setLeadId("");
    certs.reload();
  }

  function print(cert: GmCertificate) {
    const w = window.open("", "_blank");
    if (!w) return void toast.error(t("popupBlocked"));
    w.document.write(
      certificateHtml({
        org: account?.name ?? "",
        heading: t("printHeading"),
        presented: t("printPresented"),
        recipient: cert.recipient_name,
        completed: t("printCompleted"),
        course: cert.course_name,
        issuedLabel: t("colIssued"),
        issuedOn: formatDay(cert.issued_on),
        numberLabel: t("colNumber"),
        number: cert.certificate_no,
      }),
    );
    w.document.close();
  }

  async function remove(cert: GmCertificate) {
    if (!confirm(c("confirmDelete"))) return;
    const { error } = await createClient().from("gm_certificates").delete().eq("id", cert.id);
    if (error) toast.error(error.message);
    else certs.reload();
  }

  return (
    <div className="mx-auto max-w-6xl">
      <GmPageHeader
        eyebrow={c("eyebrowWorkspace")}
        title={t("title")}
        description={t("description")}
        actions={canEdit && <Button onClick={() => setOpen(true)}><Plus className="h-4 w-4" /> {t("add")}</Button>}
      />
      {certs.error && <GmError message={certs.error} />}
      <GmCard>
        {certs.loading ? (
          <GmLoading />
        ) : (
          <GmTable head={[t("colRecipient"), t("colCourse"), t("colNumber"), t("colIssued"), ""]} empty={!certs.rows.length && <GmEmpty title={t("emptyTitle")} body={t("emptyBody")} />}>
            {certs.rows.map((cert) => (
              <tr key={cert.id}>
                <GmTd><GmPerson name={cert.recipient_name} /></GmTd>
                <GmTd>{cert.course_name || "—"}</GmTd>
                <GmTd className="font-mono text-xs">{cert.certificate_no}</GmTd>
                <GmTd>{formatDay(cert.issued_on)}</GmTd>
                <GmTd className="text-right">
                  <div className="flex justify-end gap-1">
                    <Button size="sm" variant="outline" onClick={() => print(cert)}><Printer className="h-3.5 w-3.5" /> {t("print")}</Button>
                    {isAdmin && <Button size="icon-sm" variant="ghost" aria-label={c("delete")} onClick={() => remove(cert)}><Trash2 className="h-3.5 w-3.5" /></Button>}
                  </div>
                </GmTd>
              </tr>
            ))}
          </GmTable>
        )}
      </GmCard>
      <GmFormDialog open={open} onOpenChange={setOpen} title={t("addTitle")} description={t("addHint")} busy={busy} onSubmit={create} submitLabel={t("issue")}>
        <GmField label={t("fieldStudent")} wide>
          <GmSelect
            value={leadId}
            onChange={pick}
            options={[{ value: "", label: students.rows.length ? t("chooseStudent") : t("noStudents") }, ...students.rows.map((s) => ({ value: s.id, label: `${leadName(s)}${s.course ? ` · ${s.course.name}` : ""}` }))]}
          />
        </GmField>
        <GmField label={t("fieldCourse")} wide><Input value={courseName} onChange={(e) => setCourseName(e.target.value)} /></GmField>
        <GmField label={t("fieldIssued")}><Input type="date" value={issuedOn} onChange={(e) => setIssuedOn(e.target.value)} required /></GmField>
        <div className="flex items-end text-xs text-muted-foreground"><Award className="mr-1.5 h-4 w-4 text-primary" />{t("numberAuto")}</div>
      </GmFormDialog>
    </div>
  );
}
